import csv, json

def load():
    x=[]; y=[]
    with open('/app/spectrum.csv', newline='') as f:
        r=csv.reader(f)
        next(r)
        for row in r:
            if len(row) >= 2:
                x.append(float(row[0])); y.append(float(row[1]))
    return x,y

def linear_fit(x,y,x0,g):
    n=len(x); Sbb=Sb=Sby=Syy=Sy=0.0
    for xi,yi in zip(x,y):
        b=g*g/((xi-x0)*(xi-x0)+g*g)
        Sbb+=b*b; Sb+=b; Sby+=b*yi; Syy+=yi*yi; Sy+=yi
    det=Sbb*n-Sb*Sb
    if det <= 1e-15:
        return float('inf'),0.0,0.0
    A=(Sby*n-Sb*Sy)/det
    c=(Sbb*Sy-Sb*Sby)/det
    if A < 0:
        return float('inf'),A,c
    sse=Syy-2.0*A*Sby-2.0*c*Sy+A*A*Sbb+2.0*A*c*Sb+c*c*n
    if sse < 0 and sse > -1e-8:
        sse=0.0
    return sse,A,c

def fit_peak(x,y,lo,hi):
    xs=[]; ys=[]
    for xi,yi in zip(x,y):
        if lo <= xi <= hi:
            xs.append(xi); ys.append(yi)
    imax=max(range(len(ys)), key=ys.__getitem__)
    x0c=xs[imax]
    best=(float('inf'),x0c,10.0,0.0,0.0)
    x0=x0c-20.0
    while x0 <= x0c+20.0:
        if lo <= x0 <= hi:
            g=1.0
            while g <= 200.0:
                sse,A,c=linear_fit(xs,ys,x0,g)
                if sse < best[0]:
                    best=(sse,x0,g,A,c)
                g += 1.0
        x0 += 1.0
    sse,x0,g,A,c=best
    sx=1.0; sg=1.0
    while sx > 1e-5 or sg > 1e-5:
        improved=False
        for dx,dg in ((sx,0.0),(-sx,0.0),(0.0,sg),(0.0,-sg),(sx,sg),(sx,-sg),(-sx,sg),(-sx,-sg)):
            x0t=x0+dx; gt=g+dg
            if not (lo <= x0t <= hi) or gt <= 0.0:
                continue
            sse_t,A_t,c_t=linear_fit(xs,ys,x0t,gt)
            if sse_t < sse:
                sse,x0,g,A,c=sse_t,x0t,gt,A_t,c_t
                improved=True
        if not improved:
            sx*=0.5; sg*=0.5
    return {'x0':x0,'gamma':g,'amplitude':A,'offset':c}, sse

x,y=load()
out={}
for name,lo,hi in [('D',1250.0,1450.0),('G',1500.0,1660.0),('2D',2550.0,2820.0)]:
    p,sse=fit_peak(x,y,lo,hi)
    out[name]=p
    print(name, p, 'sse', sse)
out['ID_IG']=out['D']['amplitude']/out['G']['amplitude']
with open('/app/results.json','w') as f:
    json.dump(out,f,indent=2)
print('ID_IG',out['ID_IG'])
print(open('/app/results.json').read())
